import React from 'react';

function Header() {
    return (
        <header>
            <h1>Mable Zhang (Professional Cutie Pie)</h1>
            <nav>
                <a href="#about">About</a>
                <a href="#projects">Projects</a>
                <a href="#contact">Contact</a>
            </nav>
        </header>
    );
}

export default Header;
